fn wire_translated_did_set_callbacks(options: &mut [VimoptionT; OPT_COUNT]) {
    wire_option_callbacks(options);
    wire_optionstr_callbacks(options);
    wire_callback_option_callbacks(options);
    wire_other_callbacks(options);
}

